{{--
    The homepage occasion banner (Lane OHB). Drawn only when Appearance ->
    Occasion banner -> Display is not "Slider only"; App\Support\OccasionBanner
    builds $ohb from the request's settings map (no query). Every word is
    escaped; the colours matched #rrggbb and the link went through
    Banners::safeUrl() before they reach here. The stylesheet is a constant.
    The words are HTML, so they -- not a picture -- are the LCP element.
--}}<style>{!! \App\Support\OccasionBanner::css() !!}</style><div class="ohb ohb-{{ $ohb['layout'] }}{{ $ohb['animate'] ? '' : ' ohb-still' }}" style="{{ $ohb['style'] }}" role="region" aria-label="{{ $ohb['t']['title'] !== '' ? $ohb['t']['title'] : $ohb['t']['label'] }}"><div class="ohb-bg" aria-hidden="true"><i></i><i></i><i></i></div><div class="ohb-glow" aria-hidden="true"></div>@if ($ohb['layout'] === 'G')<span class="ohb-dot ohb-d1" aria-hidden="true"></span><span class="ohb-dot ohb-d2" aria-hidden="true"></span><span class="ohb-dot ohb-d3" aria-hidden="true"></span>@elseif ($ohb['layout'] === 'H')<div class="ohb-halo" aria-hidden="true"></div>@else<div class="ohb-wave" aria-hidden="true"></div><div class="ohb-wave w2" aria-hidden="true"></div>@endif
@foreach ($ohb['products'] as $ohbP)<div class="ohb-p ohb-s{{ (int) $ohbP['slot'] }}" style="{{ $ohbP['style'] }}"><img src="{{ $ohbP['src'] }}" srcset="{{ $ohbP['srcset'] }}" sizes="{{ $ohbP['sizes'] }}" width="{{ (int) $ohbP['w'] }}" height="{{ (int) $ohbP['h'] }}" alt="{{ $ohbP['alt'] }}" decoding="async" draggable="false"></div>@endforeach
<div class="ohb-copy">@if ($ohb['t']['label'] !== '')<span class="ohb-label">{{ $ohb['t']['label'] }}</span>@endif @if ($ohb['t']['num'] !== '')<span class="ohb-num" aria-hidden="true">{{ $ohb['t']['num'] }}</span>@endif @if ($ohb['t']['title'] !== '')<h2><span class="ohb-title">{{ $ohb['t']['title'] }}</span></h2>@endif @if ($ohb['t']['offer'] !== '')<div class="ohb-offer">{{ $ohb['t']['offer'] }}</div>@endif @if ($ohb['t']['line'] !== '')<p class="ohb-line">{{ $ohb['t']['line'] }}</p>@endif @if ($ohb['t']['cta'] !== '' && $ohb['href'] !== '')<a class="ohb-btn" href="{{ $ohb['href'] }}" draggable="false">{{ $ohb['t']['cta'] }} <span class="ohb-arw" aria-hidden="true">&rarr;</span></a>@endif</div></div>
